19	/**
20	 * Display a formatted list of hooks with their status
21	 */
22	async function panelAction(
23	  context: CommandContext,
24	): Promise<void | MessageActionReturn> {
25	  const { config } = context.services;
26	  if (!config) {
27	    return {
28	      type: 'message',
29	      messageType: 'error',
30	      content: 'Config not loaded.',
31	    };
32	  }
33	
34	  const hookSystem = config.getHookSystem();
35	  const allHooks = hookSystem?.getAllHooks() || [];
36	
37	  const hooksListItem: HistoryItemHooksList = {
38	    type: MessageType.HOOKS_LIST,
39	    hooks: allHooks,
40	  };
41	
42	  context.ui.addItem(hooksListItem);
43	}
