56	      kind: CommandKind.BUILT_IN,
57	      autoExecute: true,
58	      action: async (context, args): Promise<OpenCustomDialogActionReturn> => {
59	        const { config } = context.services;
60	        if (!config) {
61	          throw new Error('Config not available');
62	        }
63	
64	        let limit = 100;
65	        let until: string | undefined;
66	
67	        if (args && args.trim().length > 0) {
68	          const argArray = args.trim().split(/\s+/);
69	          for (let i = 0; i < argArray.length; i++) {
70	            const arg = argArray[i];
71	            if (arg === '--until') {
72	              if (i + 1 >= argArray.length) {
73	                throw new Error('Flag --until requires a value (YYYY-MM-DD).');
74	              }
75	              const val = argArray[i + 1];
76	              if (!/^\d{4}-\d{2}-\d{2}$/.test(val)) {
77	                throw new Error(
78	                  `Invalid date format for --until: "${val}". Expected YYYY-MM-DD.`,
79	                );
80	              }
81	              until = val;
82	              i++;
83	            } else if (arg.startsWith('--')) {
84	              throw new Error(`Unknown flag: ${arg}`);
85	            } else {
86	              const parsedLimit = parseInt(arg, 10);
87	              if (!isNaN(parsedLimit) && parsedLimit > 0) {
88	                limit = parsedLimit;
89	              } else {
90	                throw new Error(
91	                  `Invalid argument: "${arg}". Expected a positive number or --until flag.`,
92	                );
93	              }
94	            }
95	          }
96	        }
97	
98	        return {
99	          type: 'custom_dialog',
100	          component: (
