import type React from 'react';
import { useMemo, useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry rendered by the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  enabled: boolean;
  matcher?: string;
  sequential?: boolean;
}

export interface HooksDialogProps {
  /** The hooks to display, grouped by event name. */
  hooks: HookEntry[];
  /** Invoked when the dialog should be closed (e.g. Escape pressed). */
  onClose: () => void;
  /**
   * Maximum number of hooks visible at once. When the total number of hooks
   * exceeds this value the list becomes scrollable.
   */
  maxVisibleHooks?: number;
}

/**
 * Resolve the human friendly display name for a hook, falling back to the
 * command when an explicit name is not configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * An interactive dialog for browsing configured hooks. Unlike the previous
 * approach of pushing a static message into the UI feed, this component owns
 * keyboard focus so the user can scroll through hooks and dismiss the dialog
 * with Escape.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  const isScrollable =
    maxVisibleHooks !== undefined && hooks.length > maxVisibleHooks;

  const maxOffset =
    maxVisibleHooks === undefined
      ? 0
      : Math.max(0, hooks.length - maxVisibleHooks);

  useKeypress(
    (key) => {
      if (key.name === 'escape') {
        onClose();
        return;
      }

      if (!isScrollable) {
        return;
      }

      if (key.name === 'up') {
        setScrollOffset((prev) => Math.max(0, prev - 1));
      } else if (key.name === 'down') {
        setScrollOffset((prev) => Math.min(maxOffset, prev + 1));
      }
    },
    { isActive: true },
  );

  // Determine the window of hooks to display based on the scroll offset.
  const visibleHooks = useMemo(() => {
    if (maxVisibleHooks === undefined) {
      return hooks;
    }
    return hooks.slice(scrollOffset, scrollOffset + maxVisibleHooks);
  }, [hooks, maxVisibleHooks, scrollOffset]);

  // Group the visible hooks by event name for organized rendering.
  const hooksByEvent = useMemo(() => {
    return visibleHooks.reduce(
      (acc, hook) => {
        if (!acc[hook.eventName]) {
          acc[hook.eventName] = [];
        }
        acc[hook.eventName].push(hook);
        return acc;
      },
      {} as Record<string, HookEntry[]>,
    );
  }, [visibleHooks]);

  const showTopIndicator = isScrollable && scrollOffset > 0;
  const showBottomIndicator = isScrollable && scrollOffset < maxOffset;

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.border.default}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {hooks.length === 0 ? (
        <Box marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <Box flexDirection="column" paddingLeft={2} marginTop={1}>
          {showTopIndicator && (
            <Text color={theme.text.secondary}>▲</Text>
          )}
          {Object.entries(hooksByEvent).map(([eventName, eventHooks]) => (
            <Box key={eventName} flexDirection="column" marginBottom={1}>
              <Text color={theme.text.accent} bold>
                {eventName}:
              </Text>
              <Box flexDirection="column" paddingLeft={2}>
                {eventHooks.map((hook, index) => {
                  const hookName = getHookDisplayName(hook);
                  const statusColor = hook.enabled
                    ? theme.status.success
                    : theme.text.secondary;
                  const statusText = hook.enabled ? 'enabled' : 'disabled';

                  return (
                    <Box
                      key={`${eventName}-${index}`}
                      flexDirection="column"
                    >
                      <Box>
                        <Text>
                          <Text color={theme.text.accent}>{hookName}</Text>
                          <Text color={statusColor}>
                            {` [${statusText}]`}
                          </Text>
                        </Text>
                      </Box>
                      <Box paddingLeft={2} flexDirection="column">
                        {hook.config.description && (
                          <Text italic>{hook.config.description}</Text>
                        )}
                        <Text dimColor>
                          Source: {hook.source}
                          {hook.config.name &&
                            hook.config.command &&
                            ` | Command: ${hook.config.command}`}
                          {hook.matcher && ` | Matcher: ${hook.matcher}`}
                          {hook.sequential && ` | Sequential`}
                          {hook.config.timeout &&
                            ` | Timeout: ${hook.config.timeout}s`}
                        </Text>
                      </Box>
                    </Box>
                  );
                })}
              </Box>
            </Box>
          ))}
          {showBottomIndicator && (
            <Text color={theme.text.secondary}>▼</Text>
          )}
        </Box>
      )}

      <Box marginTop={1}>
        <Text dimColor>
          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text color={theme.text.secondary}>Press Esc to close.</Text>
      </Box>
    </Box>
  );
};
